package com.yuhui.operating;
import org.springframework.web.bind.annotation.*;
import org.springframework.context.annotation.Profile;
import java.time.*;
import java.util.*;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import static com.yuhui.operating.V3Store.*;

@RestController @Profile("local") @RequestMapping("/v3")
public class V3Controller {
    private final V3Store db;private final V3Campaigns campaigns;private final V3Execution execution;private final V3Review review;private final V3Demo demo;
    private final ReentrantReadWriteLock maintenance=new ReentrantReadWriteLock(true);
    public V3Controller(V3Store d,V3Campaigns c,V3Execution e,V3Review r,V3Demo g){db=d;campaigns=c;execution=e;review=r;demo=g;}
    private Object call(V3Store.Work<?> work)throws Exception{maintenance.readLock().lock();try{Object data=db.tx(work);if(data instanceof Map && ((Map<?,?>)data).containsKey("error_code"))return Map.of("code",4000,"data",data,"message",((Map<?,?>)data).get("error_code")+"："+((Map<?,?>)data).get("message"));return Map.of("code",1000,"data",data,"message","成功");}finally{maintenance.readLock().unlock();}}
    private LocalDateTime now(){return LocalDateTime.now(ZoneId.of("Asia/Shanghai"));}
    @ExceptionHandler(IllegalArgumentException.class) public Map<String,Object> invalid(IllegalArgumentException e){return Map.of("code",4000,"message",e.getMessage());}
    @GetMapping("/customers") public Object customers(@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="") String search)throws Exception{return call(c->Map.of("total",one(c,"SELECT COUNT(*) n FROM v3_customer WHERE customer_id LIKE ?","%"+search+"%").get("n"),"items",rows(c,"SELECT * FROM v3_customer WHERE customer_id LIKE ? ORDER BY customer_id LIMIT 50 OFFSET ?","%"+search+"%",Math.max(0,page-1)*50)));}
    @GetMapping("/segments") public Object segments()throws Exception{return call(c->rows(c,"SELECT * FROM v3_segment ORDER BY id"));}
    @PostMapping("/segments/preview") public Object preview(@RequestBody Map<String,Object> b)throws Exception{return call(c->campaigns.preview(c,b));}
    @PostMapping("/segments") public Object segment(@RequestBody Map<String,Object> b)throws Exception{return call(c->campaigns.segment(c,null,b));}
    @PutMapping("/segments/{id}") public Object segmentEdit(@PathVariable long id,@RequestBody Map<String,Object> b)throws Exception{return call(c->campaigns.segment(c,id,b));}
    @PostMapping("/segments/{id}/snapshots") public Object snapshot(@PathVariable long id)throws Exception{return call(c->campaigns.snapshot(c,id));}
    @GetMapping("/snapshots") public Object snapshots()throws Exception{return call(c->rows(c,"SELECT * FROM v3_segment_snapshot ORDER BY id DESC"));}
    @GetMapping("/snapshots/{id}/members") public Object members(@PathVariable long id,@RequestParam(defaultValue="1") int page)throws Exception{return call(c->rows(c,"SELECT * FROM v3_segment_snapshot_member WHERE snapshot_id=? ORDER BY customer_id LIMIT 50 OFFSET ?",id,Math.max(0,page-1)*50));}
    @GetMapping("/catalog") public Object catalog()throws Exception{return call(c->Map.of("scenes",rows(c,"SELECT * FROM v3_scene"),"merchants",rows(c,"SELECT * FROM v3_merchant"),"benefits",rows(c,"SELECT * FROM v3_benefit")));}
    @PostMapping("/merchants") public Object merchant(@RequestBody Map<String,Object> b)throws Exception{return call(c->{require(!s(b.get("name")).isBlank(),"名称不能为空");one(c,"SELECT id FROM v3_scene WHERE id=?",b.get("scene_id"));return insert(c,"INSERT INTO v3_merchant(name,district,scene_id,category) VALUES(?,?,?,?)",b.get("name"),b.get("district"),b.get("scene_id"),b.get("category"));});}
    @PostMapping("/benefits") public Object benefit(@RequestBody Map<String,Object> b)throws Exception{return call(c->{require(Set.of("COUPON","POINTS_EXCHANGE","DRAW_REWARD").contains(s(b.get("type"))),"权益类型无效");require(!s(b.get("name")).isBlank(),"名称不能为空");for(String k:List.of("face_value","minimum_spend","bank_cost","merchant_cost","points_price"))require(n(b.get(k))>=0,"金额或积分不可为负");require(n(b.get("bank_cost"))+n(b.get("merchant_cost"))==n(b.get("face_value")),"银行成本+商户让利应等于演示面值");require(n(b.get("bank_cost"))>0&&n(b.get("valid_days"))>0&&n(b.get("valid_days"))<=365&&n(b.get("total_stock"))>0,"成本、有效期、库存参数无效");require("POINTS_EXCHANGE".equals(b.get("type"))?n(b.get("points_price"))>0:n(b.get("points_price"))==0,"仅积分兑换权益需要积分价格");return insert(c,"INSERT INTO v3_benefit(name,scene_id,type,face_value,minimum_spend,bank_cost,merchant_cost,points_price,valid_days,total_stock) VALUES(?,?,?,?,?,?,?,?,?,?)",b.get("name"),b.get("scene_id"),b.get("type"),b.get("face_value"),b.get("minimum_spend"),b.get("bank_cost"),b.get("merchant_cost"),b.get("points_price"),b.get("valid_days"),b.get("total_stock"));});}
    @GetMapping("/campaigns") public Object campaigns()throws Exception{return call(c->rows(c,"SELECT * FROM v3_campaign ORDER BY id DESC"));}
    @PostMapping("/campaigns") public Object save(@RequestBody Map<String,Object> b)throws Exception{return call(c->campaigns.save(c,null,b));}
    @PutMapping("/campaigns/{id}") public Object edit(@PathVariable long id,@RequestBody Map<String,Object> b)throws Exception{return call(c->campaigns.save(c,id,b));}
    @PostMapping("/campaigns/{id}/{action:submit|approve|reject|publish}") public Object transition(@PathVariable long id,@PathVariable String action)throws Exception{return call(c->campaigns.transition(c,id,action));}
    @GetMapping("/versions") public Object versions()throws Exception{return call(c->rows(c,"SELECT * FROM v3_campaign_version ORDER BY id DESC"));}
    @PostMapping("/versions/{id}/runs") public Object run(@PathVariable long id,@RequestBody(required=false) Map<String,Object> body)throws Exception{return call(c->campaigns.run(c,id,body==null||body.get("allocated_budget")==null?null:n(body.get("allocated_budget"))));}
    @GetMapping("/runs") public Object runs()throws Exception{return call(c->rows(c,"SELECT r.*,a.name FROM v3_campaign_run r JOIN v3_campaign a ON a.id=r.campaign_id ORDER BY r.id DESC"));}
    @PostMapping("/runs/{id}/end") public Object end(@PathVariable long id)throws Exception{return call(c->{execution.end(c,id);return true;});}
    @PostMapping("/runs/{id}/events") public Object event(@PathVariable long id,@RequestBody Map<String,Object> b)throws Exception{return call(c->execution.record(c,id,s(b.get("customer_id")),s(b.get("event_type")),s(b.get("action")),now()));}
    @PostMapping("/runs/{id}/claim") public Object claim(@PathVariable long id,@RequestBody Map<String,Object> b)throws Exception{return call(c->execution.claim(c,id,s(b.get("customer_id")),n(b.get("merchant_id")),now()));}
    @GetMapping("/runs/{id}/review") public Object review(@PathVariable long id)throws Exception{return call(c->review.review(c,id));}
    @PostMapping("/runs/{id}/decisions") public Object decision(@PathVariable long id,@RequestBody Map<String,Object> b)throws Exception{return call(c->review.decision(c,id,b));}
    @GetMapping("/runs/{id}/ledger") public Object ledger(@PathVariable long id,@RequestParam(defaultValue="event") String type,@RequestParam(defaultValue="") String eventType,@RequestParam(defaultValue="1") int page)throws Exception{return call(c->{require(Set.of("event","budget").contains(type),"账本类型无效");String filter=type.equals("event")&&!eventType.isBlank()?" AND event_type=?":"";List<Object> args=new ArrayList<>();args.add(id);if(!filter.isEmpty())args.add(eventType);long total=n(one(c,"SELECT COUNT(*) n FROM v3_"+type+"_ledger WHERE campaign_run_id=?"+filter,args.toArray()).get("n"));args.add(Math.max(0,page-1)*100);return Map.of("total",total,"items",rows(c,"SELECT * FROM v3_"+type+"_ledger WHERE campaign_run_id=?"+filter+" ORDER BY id LIMIT 100 OFFSET ?",args.toArray()));});}
    @GetMapping("/wallet") public Object wallet(@RequestParam String customerId)throws Exception{return call(c->{List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> e:rows(c,"SELECT * FROM v3_entitlement WHERE customer_id=? ORDER BY id DESC",customerId))out.add(V3Execution.publicEntitlement(e));return out;});}
    @GetMapping("/offers") public Object offers(@RequestParam String customerId)throws Exception{return call(c->{List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> r:rows(c,"SELECT r.* FROM v3_campaign_run r JOIN v3_segment_snapshot_member m ON m.snapshot_id=r.segment_snapshot_id JOIN v3_customer u ON u.customer_id=m.customer_id WHERE m.customer_id=? AND u.marketing_consent=1 AND r.status='RUNNING' AND r.start_time<=? AND r.end_time>=?",customerId,now(),now())){Map<String,Object> cfg=obj(execution.run(c,n(r.get("id"))).get("config_json")),b=new LinkedHashMap<>((Map<String,Object>)cfg.get("benefit"));b.remove("bank_cost");b.remove("merchant_cost");out.add(Map.of("run_id",r.get("id"),"name",cfg.get("name"),"benefit",b,"merchants",cfg.get("merchants")));}return out;});}
    @GetMapping("/entitlements/{code}") public Object entitlement(@PathVariable String code)throws Exception{return call(c->V3Execution.publicEntitlement(one(c,"SELECT * FROM v3_entitlement WHERE code=?",code)));}
    @PostMapping("/redeem") public Object redeem(@RequestBody Map<String,Object> b)throws Exception{return call(c->execution.redeem(c,s(b.get("code")),n(b.get("merchant_id")),n(b.get("mock_spend")),now()));}
    @PostMapping("/cancel") public Object cancel(@RequestBody Map<String,Object> b)throws Exception{return call(c->execution.release(c,s(b.get("code")),true,s(b.get("customer_id")),now()));}
    @org.springframework.scheduling.annotation.Scheduled(fixedDelay=60000, initialDelay=60000)
    public void scheduledExpiry() throws Exception { expire(); }
    @PostMapping("/expire") public Object expire()throws Exception{return call(c->execution.expire(c,now()));}
    @GetMapping("/overview") public Object overview()throws Exception{return call(c->{List<Map<String,Object>> rs=rows(c,"SELECT r.*,a.name FROM v3_campaign_run r JOIN v3_campaign a ON a.id=r.campaign_id ORDER BY id DESC");for(Map<String,Object> r:rs){Map<String,Object> result=review.review(c,n(r.get("id")));r.put("budget",result.get("budget"));r.put("warnings",result.get("warnings"));}return Map.of("runs",rs,"pending",rows(c,"SELECT id,name FROM v3_campaign WHERE status='PENDING_REVIEW'"),"needs_review",rows(c,"SELECT r.id,a.name FROM v3_campaign_run r JOIN v3_campaign a ON a.id=r.campaign_id WHERE r.status='ENDED' AND NOT EXISTS(SELECT 1 FROM v3_decision_record d WHERE d.campaign_run_id=r.id)"));});}
    @PostMapping("/demo/reset") public Object reset(@RequestBody Map<String,Object> b)throws Exception{require("RESET_V3_DEMO".equals(b.get("confirmation")),"需要明确确认重置 V3 演示数据");maintenance.writeLock().lock();try{return Map.of("code",1000,"data",db.tx(c->demo.reset(c,n(b.getOrDefault("seed",202610)))));}finally{maintenance.writeLock().unlock();}}
}
